def current_rows(events):
    latest = {}
    for e in events:
        eid = e['id']
        key = (e['event_time'], e['seq'])
        if eid not in latest or key > (latest[eid]['event_time'], latest[eid]['seq']):
            latest[eid] = e

    return [
        {'id': eid, 'value': e['value']}
        for eid, e in sorted(latest.items())
        if e['op'] != 'D'
    ]

import heapq

def stable_toposort(graph):
    order = {node: i for i, node in enumerate(graph)}
    indegree = {node: 0 for node in graph}
    adj = {node: [] for node in graph}

    for node, deps in graph.items():
        for dep in deps:
            if dep not in graph:
                raise ValueError("missing dependency")
            indegree[node] += 1
            adj[dep].append(node)

    heap = []
    for node, i in order.items():
        if indegree[node] == 0:
            heapq.heappush(heap, (i, node))

    result = []
    while heap:
        _, node = heapq.heappop(heap)
        result.append(node)

        for dependent in adj[node]:
            indegree[dependent] -= 1
            if indegree[dependent] == 0:
                heapq.heappush(heap, (order[dependent], dependent))

    if len(result) != len(graph):
        raise ValueError("cycle")

    return result

