def schema_drift(expected, actual):
    result = []

    def walk(exp, act, path):
        for key in sorted(set(exp) | set(act)):
            p = f"{path}.{key}" if path else key

            if key not in act:
                if isinstance(exp[key], dict):
                    walk(exp[key], {}, p)
                else:
                    result.append(p)
            elif key not in exp:
                if isinstance(act[key], dict):
                    walk({}, act[key], p)
                else:
                    result.append(p)
            else:
                if isinstance(exp[key], dict) and isinstance(act[key], dict):
                    walk(exp[key], act[key], p)
                elif exp[key] != act[key]:
                    result.append(p)

    walk(expected, actual, "")
    return sorted(result)
