def merge_payload_ranges(items):
    merged = []
    for start, end, payload in sorted(items, key=lambda x: (x[0], x[1])):
        if start > end:
            raise ValueError("start > end")
        if not merged:
            merged.append([start, end, payload])
            continue
        last = merged[-1]
        if payload == last[2] and start <= last[1]:
            if end > last[1]:
                last[1] = end
        else:
            merged.append([start, end, payload])
    return merged

def committable_windows(events, watermark):
    result = {}
    for event in events:
        if event['event_time'] > watermark:
            window = event['window']
            if window not in result:
                result[window] = []
            result[window].append(event['value'])
    return result
